import logging
import logging.handlers

from ta_logcollector.settings import LOGGER_PORT

logger_configured = False


def _configure_logger(log_host, log_port):
    # type: (str, int) -> None
    """
    Configure only one root logger with socket and without stream handler.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    root_logger = logging.getLogger("lc")
    root_logger.setLevel(logging.DEBUG)
    for hdlr in root_logger.handlers:
        if isinstance(hdlr, logging.handlers.SocketHandler):
            break
    else:
        socket_handler = logging.handlers.SocketHandler(log_host, log_port)
        root_logger.addHandler(socket_handler)
    global logger_configured
    logger_configured = True


def get_net_logger(log_host, log_port=LOGGER_PORT, name=None):
    # type: (str, int, str) -> logging.Logger
    """
    Return instance of socket logger.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    :param name: logger name
    :return: logger instance
    """
    if not logger_configured:
        _configure_logger(log_host, log_port)
    logger = logging.getLogger("lc.{}".format(name))
    return logger
